package stream

import (
	"encoding/json"
	"strings"
	"testing"
)

// TestDescribeCodecs is the spec floor for the descriptor's additive codecs
// field (playback-capability-gate "Playback descriptor and verb split", the
// codecs paragraph; design D2/D6): an hls answer carries the pack's RFC 6381
// codec strings — the recorded value (persisted at publish) winning over the
// read-side legacy composition from the stored source ffprobe facts, video
// first then audio — while a build whose codecs cannot be composed either way
// answers no codecs and a direct answer never carries one. The projection is
// read-side only: the document is never written, nothing is re-probed.
func TestDescribeCodecs(t *testing.T) {
	// Source facts the composition table accepts: h264 High level 41 and AAC-LC.
	const composable = `{"streams":[` +
		`{"codec_type":"video","codec_name":"h264","profile":"High","level":41},` +
		`{"codec_type":"audio","codec_name":"aac","profile":"LC"}],` +
		`"format":{"format_name":"matroska,webm"}}`
	// The same codecs with the profile/level facts absent — the table composes
	// nothing (the legacy fallback's fail-open half).
	const uncomposable = `{"streams":[` +
		`{"codec_type":"video","codec_name":"h264"},` +
		`{"codec_type":"audio","codec_name":"aac"}],` +
		`"format":{"format_name":"matroska,webm"}}`
	facts := func(raw string) map[string]any {
		t.Helper()
		var f map[string]any
		if err := json.Unmarshal([]byte(raw), &f); err != nil {
			t.Fatalf("unmarshal ffprobe fixture: %v", err)
		}
		return f
	}
	// A partial namespace answers hls without an on-disk build (the integrity
	// guard exempts partial builds) — the cheapest honest hls fixture.
	hlsDoc := func(streams map[string]any) map[string]any {
		return map[string]any{"streams": streams}
	}

	s := &Service{Secret: []byte("k"), Root: t.TempDir()}

	t.Run("packaged_descriptor_carries_recorded_codecs", func(t *testing.T) {
		d := hlsDoc(map[string]any{
			"state":    StatePartial,
			"playlist": "/media/it/n0/index.m3u8",
			"codecs":   []any{"avc1.640029", "mp4a.40.2"},
		})
		mode, _, playURL, _, _, _, codecs := s.Describe("it", d)
		if mode != ModeHls {
			t.Fatalf("mode = %q, want hls", mode)
		}
		if len(codecs) != 2 || codecs[0] != "avc1.640029" || codecs[1] != "mp4a.40.2" {
			t.Fatalf("codecs = %v, want the recorded record in rendition order", codecs)
		}
		if !strings.HasPrefix(playURL, "/media/it/n0/index.m3u8?"+tokenQuery+"=") {
			t.Fatalf("playURL = %q, want the playable playlist URL retained", playURL)
		}
	})

	t.Run("recorded_value_wins_over_source_facts", func(t *testing.T) {
		d := hlsDoc(map[string]any{
			"state":    StatePartial,
			"playlist": "/media/it/n0/index.m3u8",
			"codecs":   []any{"hvc1.1.6.L93.B0", "mp4a.40.2"},
		})
		d["ffprobe"] = facts(composable) // would compose avc1… — the record must win
		_, _, _, _, _, _, codecs := s.Describe("it", d)
		if len(codecs) != 2 || codecs[0] != "hvc1.1.6.L93.B0" {
			t.Fatalf("codecs = %v, want the recorded value to win verbatim", codecs)
		}
	})

	// Scenario: Legacy build answers codecs composed from stored facts.
	t.Run("legacy_build_composes_from_stored_facts", func(t *testing.T) {
		d := hlsDoc(map[string]any{
			"state":    StatePartial,
			"playlist": "/media/it/n0/index.m3u8",
		})
		d["ffprobe"] = facts(composable) // a namespace predating the record
		mode, _, _, _, _, _, codecs := s.Describe("it", d)
		if mode != ModeHls {
			t.Fatalf("mode = %q, want hls", mode)
		}
		// Video first, then audio — composed through the same table the
		// publish path uses: High level 41 → avc1.640029, AAC-LC → mp4a.40.2.
		if len(codecs) != 2 || codecs[0] != "avc1.640029" || codecs[1] != "mp4a.40.2" {
			t.Fatalf("codecs = %v, want the legacy composition avc1.640029,mp4a.40.2", codecs)
		}
	})

	t.Run("uncomposable_legacy_answers_no_codecs_keeps_play_url", func(t *testing.T) {
		d := hlsDoc(map[string]any{
			"state":    StatePartial,
			"playlist": "/media/it/n0/index.m3u8",
		})
		d["ffprobe"] = facts(uncomposable)
		mode, _, playURL, _, _, _, codecs := s.Describe("it", d)
		if mode != ModeHls || codecs != nil {
			t.Fatalf("descriptor = %q/%v, want hls with no codecs field (fail-open)", mode, codecs)
		}
		if !strings.HasPrefix(playURL, "/media/it/n0/index.m3u8?"+tokenQuery+"=") {
			t.Fatalf("playURL = %q, want the playable playlist URL kept", playURL)
		}
	})

	t.Run("unreadable_record_degrades_to_legacy", func(t *testing.T) {
		d := hlsDoc(map[string]any{
			"state":    StatePartial,
			"playlist": "/media/it/n0/index.m3u8",
			"codecs":   []any{"avc1.640029", 42}, // one unreadable entry
		})
		d["ffprobe"] = facts(composable)
		_, _, _, _, _, _, codecs := s.Describe("it", d)
		if len(codecs) != 2 || codecs[0] != "avc1.640029" || codecs[1] != "mp4a.40.2" {
			t.Fatalf("codecs = %v, want the legacy composition behind the broken record", codecs)
		}
	})

	// Scenario: a direct answer for another item in the same session carries
	// no codecs field — the field describes the pack.
	t.Run("direct_answers_never_carry_codecs", func(t *testing.T) {
		d := map[string]any{"ffprobe": facts(composable)}
		mode, _, _, _, _, reason, codecs := s.Describe("it", d)
		if mode != ModeDirect || codecs != nil {
			t.Fatalf("descriptor = %q/%v, want direct with no codecs", mode, codecs)
		}
		if reason != ReasonNonNativeContainer {
			t.Fatalf("reason = %q, want %q (the composable floor is preparing)", reason, ReasonNonNativeContainer)
		}
	})
}
